    u_xlat0.y = float(u_xlati0);
    u_xlatb1 = _Layout==1;
    u_xlat2.x = float(unity_StereoEyeIndex);
    u_xlat2.y = float(0.0);
    u_xlat2.z = float(0.5);
    u_xlat2.w = float(1.0);
    u_xlat0.x = float(0.0);
    u_xlat0.z = float(1.0);
    u_xlat0.w = float(0.5);
    u_xlat0 = (bool(u_xlatb1)) ? u_xlat2 : u_xlat0;
    vs_TEXCOORD2 = (int(_Layout) != 0) ? u_xlat0 : vec4(0.0, 0.0, 1.0, 1.0);
